export class BindVertexArrayOES extends BaseValue<any> {
    getDefault(): any {
        return null;
    }
    set(v: any) {
        if (!this.gl || (v === this.current && !this.dirty)) return;
        this.gl.bindVertexArray(v);
        this.current = v;
        this.dirty = false;
